/**
 * Regenerates src/pages/guides/guideIndex.ts from the guide configs.
 *
 * Run after adding, removing or renaming a guide:  npm run gen:guides
 *
 * The index holds each guide's slug, cluster, title and summary, plus a
 * per-cluster dynamic import. It exists so routes.tsx and the /guides hub can
 * be built without pulling ~600KB of guide prose into the main bundle. It is a
 * generated file: edit the guides, then rerun this. `npm run audit:qa` fails
 * the build if the two ever disagree.
 */
import { readFileSync, writeFileSync, readdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';

const DIR = 'src/pages/guides';
const TMP = '.tmp-guide-index';

execFileSync('npx', ['vite', 'build', '--ssr', `${DIR}/guideData.ts`, '--outDir', TMP, '--logLevel', 'error'], {
  stdio: 'inherit',
});

const { guideConfigs } = await import(`../${TMP}/guideData.js`);

const owner = {};
for (const file of readdirSync(DIR).filter((f) => f.endsWith('.ts') && f !== 'guideIndex.ts')) {
  const src = readFileSync(join(DIR, file), 'utf8');
  const re = /export const (\w+): GuideConfig = \{\s*\n\s*slug: '([^']+)'/g;
  let m;
  while ((m = re.exec(src)) !== null) {
    owner[m[2]] = { file, module: './' + file.replace(/\.ts$/, ''), exportName: m[1] };
  }
}

const unmapped = guideConfigs.filter((c) => !owner[c.slug]).map((c) => c.slug);
if (unmapped.length) {
  console.error(`Could not locate the source for: ${unmapped.join(', ')}`);
  process.exit(1);
}

const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, ' ');
const entries = guideConfigs
  .map((c) => `  {\n    slug: '${esc(c.slug)}',\n    cluster: '${esc(c.cluster)}',\n    title: '${esc(c.h1)}',\n    summary: '${esc(c.summary)}',\n  },`)
  .join('\n');
const loaders = guideConfigs
  .map((c) => `  '${c.slug}': () => import('${owner[c.slug].module}').then((m) => m.${owner[c.slug].exportName}),`)
  .join('\n');
const modules = guideConfigs.map((c) => `  '${c.slug}': '${DIR}/${owner[c.slug].file}',`).join('\n');

writeFileSync(
  `${DIR}/guideIndex.ts`,
  `import type { GuideConfig } from './types';

/**
 * Lightweight index of every guide: enough to build the route table and the
 * hub cards, and nothing else.
 *
 * GENERATED by scripts/gen-guide-index.mjs — run \`npm run gen:guides\` after
 * changing a guide's slug, cluster, h1 or summary. Do not edit by hand.
 *
 * The full configs carry ~600KB of prose. routes.tsx and the route manifest
 * both imported them eagerly, so someone who opened the editor to make a
 * single invoice downloaded every guide first. This file lets the route table
 * be built without touching that prose; \`guideLoaders\` then fetches a guide's
 * cluster only when that guide is actually visited.
 */
export interface GuideIndexEntry {
  slug: string;
  cluster: string;
  title: string;
  summary: string;
}

export const guideIndex: GuideIndexEntry[] = [
${entries}
];

export const guideSlugs: string[] = guideIndex.map((g) => g.slug);

/** Per-cluster dynamic imports, so one guide never drags in the rest. */
export const guideLoaders: Record<string, () => Promise<GuideConfig>> = {
${loaders}
};

/**
 * Source module each guide lives in. Build-time only: the prerenderer maps this
 * through Vite's manifest to emit a <link rel="modulepreload"> for the cluster
 * chunk, so the split costs the reader no visible delay.
 */
export const guideModulePath: Record<string, string> = {
${modules}
};
`,
);

rmSync(TMP, { recursive: true, force: true });
console.log(`  guideIndex.ts regenerated: ${guideConfigs.length} guides`);
